public List<AclRequestsResponseModel> getAclRequests(
    String pageNo,
    String currentPage,
    String requestStatus,
    RequestOperationType requestOperationType,
    String topic,
    String env,
    String search,
    AclType aclType,
    boolean isMyRequest) {

  String userName = getCurrentUserName();
  int tenantId = commonUtilsService.getTenantId(userName);
  HandleDbRequests dbHandle = manageDatabase.getHandleDbRequests();
  List<AclRequests> aclReqs =
      dbHandle.getAllAclRequests(
          false,
          userName,
          "",
          requestStatus,
          false,
          requestOperationType,
          topic,
          env,
          search,
          aclType,
          isMyRequest,
          tenantId);

  // tenant filtering
  final Set<String> allowedEnvIdSet = commonUtilsService.getEnvsFromUserId(userName);
  aclReqs =
      aclReqs.stream()
          .filter(aclRequest -> allowedEnvIdSet.contains(aclRequest.getEnvironment()))
          .sorted(Collections.reverseOrder(Comparator.comparing(AclRequests::getRequesttime)))
          .collect(Collectors.toList());

  aclReqs = getAclRequestsPaged(aclReqs, pageNo, currentPage, tenantId);

  return getAclRequestsModels(aclReqs, tenantId, userName);
}

