public List<AclRequestsModel> getCreatedAclRequests(
    String pageNo,
    String currentPage,
    String requestsType,
    String topic,
    String environment,
    AclType aclType) {
  log.debug("getCreatedAclRequests {} {}", pageNo, requestsType);
  String userDetails = getCurrentUserName();
  List<AclRequests> createdAclReqs;
  int tenantId = commonUtilsService.getTenantId(userDetails);

  // get requests relevant to your teams or all teams
  if (commonUtilsService.isNotAuthorizedUser(
      getPrincipal(), PermissionType.APPROVE_ALL_REQUESTS_TEAMS)) {
    createdAclReqs =
        manageDatabase
            .getHandleDbRequests()
            .getCreatedAclRequestsByStatus(
                userDetails, requestsType, false, topic, environment, aclType, tenantId);
  } else {
    createdAclReqs =
        manageDatabase
            .getHandleDbRequests()
            .getCreatedAclRequestsByStatus(
                userDetails, requestsType, true, topic, environment, aclType, tenantId);
  }

  // tenant filtering
  final Set<String> allowedEnvIdSet = commonUtilsService.getEnvsFromUserId(userDetails);
  createdAclReqs =
      createdAclReqs.stream()
          .filter(aclRequest -> allowedEnvIdSet.contains(aclRequest.getEnvironment()))
          .collect(Collectors.toList());

  return getAclRequestModelPaged(
      updateCreatAclReqsList(createdAclReqs, tenantId), pageNo, currentPage, tenantId);
}

